#define main legacy_main
#include "../zoom-cuda/main.cu"
#undef main
#include <vector>
#include <tuple>
#include <fstream>
#include <iostream>
#include <iomanip>
struct Case{int N,C,H,W,Ho,Wo,pitch,hs,he,ws,we,mode,smem;float zh,zw;std::vector<float>x,ref;float*a,*o;dim3 block,grid,grid2;};
int main(){std::vector<Case>cases;std::vector<float>prefix;for(auto shape:std::vector<std::vector<int>>{{2,3,17,19},{1,2,32,33}})for(int fixture:{0,1})for(int mode:{1,2}){Case c;c.N=shape[0];c.C=shape[1];c.H=shape[2];c.W=shape[3];c.mode=mode;c.zh=mode==1?1.5f:0.6f;c.zw=mode==1?2.5f:0.9f;c.Ho=floorf(c.H*c.zh);c.Wo=floorf(c.W*c.zw);c.pitch=c.H*c.W;c.hs=abs(c.H-c.Ho)/2;c.ws=abs(c.W-c.Wo)/2;c.he=mode==1?c.H+c.hs:c.H-c.Ho-c.hs;c.we=mode==1?c.W+c.ws:c.W-c.Wo-c.ws;int sizes[]={c.N,c.C,c.Ho,c.Wo};c.smem=get_sm_size(sizes,c.H,c.W,c.block);c.grid=dim3((c.Wo+15)/16,(c.Ho+15)/16,c.N*c.C);c.grid2=dim3((c.W+15)/16,(c.H+15)/16,c.N*c.C);c.x.resize(c.N*c.C*c.pitch);for(int i=0;i<int(c.x.size());i++)c.x[i]=fixture==0?float((i*17)%97-48)/16:1;c.ref.assign(c.x.size(),0);cudaMalloc(&c.a,c.x.size()*4);cudaMalloc(&c.o,c.x.size()*4);cudaMemcpy(c.a,c.x.data(),c.x.size()*4,cudaMemcpyHostToDevice);if(mode==1)zoom_in_reference(c.x.data(),c.ref.data(),c.H,c.W,c.Ho,c.Wo,c.pitch,c.hs,c.he,c.ws,c.we,c.N*c.C);else{zoom_out_reference(c.x.data(),c.ref.data(),c.H,c.W,c.Ho,c.Wo,c.pitch,c.hs,c.he,c.ws,c.we,c.N*c.C);zoom_out_edge_pad_reference(c.ref.data(),c.H,c.W,c.pitch,c.hs,c.ws,c.hs+c.Ho,c.ws+c.Wo,c.N*c.C);}prefix.insert(prefix.end(),c.x.begin(),c.x.end());for(int x:{c.N,c.C,c.H,c.W,c.Ho,c.Wo,c.pitch,c.hs,c.he,c.ws,c.we,c.mode,c.smem,3})prefix.push_back(x);prefix.push_back(c.zh);prefix.push_back(c.zw);cases.push_back(c);}
auto run=[&](Case&c,std::vector<float>&out){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++){cudaMemset(c.o,0,c.x.size()*4);if(c.mode==1)zoom_in_kernel<<<c.grid,c.block,c.smem>>>(c.a,c.o,c.H,c.W,c.Ho,c.Wo,c.pitch,c.hs,c.he,c.ws,c.we);else{zoom_out_kernel<<<c.grid,c.block,c.smem>>>(c.a,c.o,c.H,c.W,c.Ho,c.Wo,c.pitch,c.hs,c.he,c.ws,c.we);zoom_out_edge_pad<<<c.grid2,c.block>>>(c.o,c.H,c.W,c.pitch,c.hs,c.ws,c.hs+c.Ho,c.ws+c.Wo);}}cudaDeviceSynchronize();double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<float>v(c.x.size());cudaMemcpy(v.data(),c.o,v.size()*4,cudaMemcpyDeviceToHost);bool ok=cudaGetLastError()==cudaSuccess;double err=0;for(size_t i=0;i<v.size();i++){ok&=std::isfinite(v[i]);err=std::max(err,double(fabsf(v[i]-c.ref[i])));}ok&=err<=1e-4;out.insert(out.end(),v.begin(),v.end());return std::make_tuple(t,ok,err);};std::vector<float>tmp;for(auto&c:cases)run(c,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double elapsed=0,err=0;bool ok=true;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){auto[t,pass,e]=run(c,out);elapsed+=t;ok&=pass;err=std::max(err,e);std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":"<<err<<",\"timing_region\":\"sum8_three_reset_zoom_pipeline_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
